// Canal SIMULADO (no es una red real): pierde alrededor del 20 % y demora cada datagrama un tiempo al azar.
let semilla = 11;
function azar() { semilla = (semilla * 1664525 + 1013904223) % 4294967296; return semilla / 4294967296; }

const enviados = [];
for (let n = 1; n <= 12; n++) {
  enviados.push({ n, llegaEn: n + azar() * 3.5, perdido: azar() < 0.2 });
}
const llegan = enviados.filter((d) => !d.perdido).sort((a, b) => a.llegaEn - b.llegaEn);
console.log('enviados : ' + enviados.map((d) => d.n).join(' '));
console.log('llegaron : ' + llegan.map((d) => d.n).join(' '));

// Receptor: solo tiene el número que el emisor escribió adentro de cada datagrama.
let mayor = 0;
const faltan = new Set();
for (const d of llegan) {
  if (d.n > mayor + 1) {
    for (let k = mayor + 1; k < d.n; k++) faltan.add(k);
    console.log('llegó ' + d.n + ': salto desde ' + mayor + ', faltan ' + [...faltan].join(', '));
  } else if (d.n < mayor) {
    faltan.delete(d.n);
    console.log('llegó ' + d.n + ': tarde (ya había llegado el ' + mayor + ')');
  } else {
    console.log('llegó ' + d.n + ': en orden');
  }
  mayor = Math.max(mayor, d.n);
}
console.log('perdidos para siempre: ' + ([...faltan].join(', ') || 'ninguno'));
console.log('Nada se retransmitió: UDP no lo hace.');
